(function() {
    'use strict';

    var ROUTE_DATA = {
        A: { transit: 14, cost: 42, baseProb: 0.75 },
        B: { transit: 12, cost: 64, baseProb: 0.65 },
        C: { transit: 16, cost: 78, baseProb: 0.50 }
    };

    var DISRUPTION_DATA = {
        A: { transit: 21, costAdd: 0,  baseProb: 0.35, airCost: 0,      label: 'Wait — Buenaventura backlog' },
        B: { transit: 14, costAdd: 22, baseProb: 0.60, airCost: 0,      label: 'Divert to Tumaco' },
        C: { transit: 17, costAdd: 36, baseProb: 0.55, airCost: 0,      label: 'Multimodal IIRSA road' },
        D: { transit: 14, costAdd: 0,  baseProb: 0.90, airCost: 480000, label: 'Air-freight bridge 600t' }
    };

    class AndinaCorridorAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Pacific-Andean Corridor — Andina Logistics';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: 38000,
                    probArrival: 0,
                    transitDays: 0,
                    landedCost: 0,
                    deadlineDays: 18,
                    airCost: 0,
                    rebate: 0,
                    volumeCommitment: false,
                    routeChoice: null,
                    bufferDays: 0,
                    disruptionChoice: null,
                    vuceChoice: null,
                    aeoChoice: null,
                    extensionChoice: null,
                    finalRouteChoice: null,
                    contingencyChoice: null,
                    kpiChoice: null,
                    probHistory: [],
                    marginHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    route: 'A',
                    buffer: 2,
                    disruption: 'B',
                    vuce: 'parallel',
                    aeo: 'yes',
                    extension: 'paired',
                    finalRoute: 'keep',
                    contingency: 'defined',
                    kpi: 'prob'
                };
            }
            var self = this;
            setTimeout(function() { self._updateRound(state); }, 100);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var round = state.currentPeriod || 1;

            if (round === 1) {
                var sel = document.getElementById('routeSelect');
                var buf = document.getElementById('bufferInput');
                if (sel) decisions.route = sel.value;
                if (buf) decisions.buffer = parseInt(buf.value, 10) || 0;
                if (decisions.buffer < 0 || decisions.buffer > 5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('buffer_warning'), 'warning'
                    );
                    return false;
                }
            } else if (round === 2) {
                var d = document.getElementById('disruptionSelect');
                if (d) decisions.disruption = d.value;
            } else if (round === 3) {
                var v = document.getElementById('vuceSelect');
                var a = document.getElementById('aeoSelect');
                var e = document.getElementById('extensionSelect');
                if (v) decisions.vuce = v.value;
                if (a) decisions.aeo = a.value;
                if (e) decisions.extension = e.value;
            } else if (round === 4) {
                var fr = document.getElementById('finalRouteSelect');
                var ct = document.getElementById('contingencySelect');
                var kp = document.getElementById('kpiSelect');
                if (fr) decisions.finalRoute = fr.value;
                if (ct) decisions.contingency = ct.value;
                if (kp) decisions.kpi = kp.value;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            if (round === 1) {
                ds.routeChoice = d.route;
                ds.bufferDays = d.buffer;
                var r = ROUTE_DATA[d.route] || ROUTE_DATA.A;
                ds.transitDays = r.transit;
                ds.landedCost = r.cost;
                ds.probArrival = Math.min(0.95, r.baseProb + (d.buffer * 0.02));
                ds.airCost = 0;
                ds.rebate = 0;
                ds.deadlineDays = 18;
                ds.volumeCommitment = false;
            } else if (round === 2) {
                ds.disruptionChoice = d.disruption;
                var rr = DISRUPTION_DATA[d.disruption] || DISRUPTION_DATA.B;
                ds.transitDays = rr.transit;
                ds.landedCost = (ROUTE_DATA[ds.routeChoice || 'A'].cost) + rr.costAdd;
                ds.probArrival = Math.min(0.97, rr.baseProb + (ds.bufferDays * 0.015));
                ds.airCost = rr.airCost;
            } else if (round === 3) {
                ds.vuceChoice = d.vuce;
                ds.aeoChoice = d.aeo;
                ds.extensionChoice = d.extension;
                var probDelta = 0;
                if (d.vuce === 'parallel') probDelta += 0.12;
                else probDelta -= 0.10;
                if (d.aeo === 'yes' && d.vuce === 'parallel') probDelta += 0.08;
                if (d.aeo === 'yes' && d.vuce === 'sequential') probDelta -= 0.04;
                if (d.aeo === 'no' && d.vuce === 'sequential') probDelta -= 0.06;
                ds.probArrival = Math.max(0.05, Math.min(0.98, ds.probArrival + probDelta));

                if (d.extension === 'none') {
                    ds.deadlineDays = 18;
                    ds.rebate = 0;
                    ds.volumeCommitment = false;
                } else if (d.extension === 'rebate_only') {
                    ds.deadlineDays = 22;
                    ds.rebate = 5520;
                    ds.volumeCommitment = false;
                } else if (d.extension === 'paired') {
                    ds.deadlineDays = 22;
                    ds.rebate = 5520;
                    ds.volumeCommitment = true;
                }
            } else if (round === 4) {
                ds.finalRouteChoice = d.finalRoute;
                ds.contingencyChoice = d.contingency;
                ds.kpiChoice = d.kpi;
                if (d.finalRoute === 'hedge') {
                    ds.airCost = (ds.airCost || 0) + 240000;
                    ds.probArrival = Math.min(0.98, ds.probArrival + 0.05);
                }
                if (d.contingency === 'defined') {
                    ds.probArrival = Math.min(0.98, ds.probArrival + 0.03);
                }
            }

            var deadline = ds.deadlineDays || 18;
            var pointEstimateLate = Math.max(0, ds.transitDays - deadline);
            var tailDaysLate = Math.max(pointEstimateLate, 4);
            var expectedPenalty = (1 - ds.probArrival) * 9500 * tailDaysLate;

            var baselineCost = 42;
            var totalTonnes = 4200;
            var costAddTotal = (ds.landedCost - baselineCost) * totalTonnes;
            var airCost = ds.airCost || 0;
            var rebate = ds.rebate || 0;
            var volumeBonus = ds.volumeCommitment ? 8000 : 0;

            var expectedMargin = 38000 - costAddTotal - airCost - rebate - expectedPenalty + volumeBonus;
            ds.margin = expectedMargin;

            ds.probHistory.push(Math.round(ds.probArrival * 100));
            ds.marginHistory.push(Math.round(expectedMargin));

            // v1.1.0 FIX: persist a normalized 0-100 score so the instructor results
            // panel (results_utils.php express_resolveDomainScore reads
            // domainState.performance.overallScore) shows a real score instead of "-".
            // Additive only; round-by-round routing/penalty logic is unchanged.
            var _score = this._computeScore(ds);
            ds.performance = {
                overallScore: _score,
                finalProbability: Math.round(ds.probArrival * 100),
                finalMargin: Math.round(expectedMargin)
            };

            var self = this;
            setTimeout(function() {
                self._updateRound({ currentPeriod: state.currentPeriod + 1 });
            }, 400);

            return {
                round: state.currentPeriod,
                routeLabel: this._currentRouteLabel(ds, round),
                transitDays: ds.transitDays,
                landedCost: ds.landedCost,
                probArrival: ds.probArrival,
                expectedPenalty: Math.round(expectedPenalty),
                margin: Math.round(expectedMargin)
            };
        }

        _computeScore(ds) {
            // Composite 0-100: probability-weighted on-time delivery is the headline
            // (correct) KPI, plus a margin component and a small correct-KPI-framing bonus.
            var prob = Math.max(0, Math.min(1, ds.probArrival || 0));
            var marginNorm = Math.max(0, Math.min(1, (ds.margin || 0) / 40000));
            var kpiBonus = (ds.kpiChoice === 'prob') ? 10 : 0;
            var raw = (prob * 70) + (marginNorm * 20) + kpiBonus;
            return Math.round(Math.max(0, Math.min(100, raw)));
        }

        _currentRouteLabel(ds, round) {
            if (round >= 2 && ds.disruptionChoice) {
                return (DISRUPTION_DATA[ds.disruptionChoice] || {}).label || ds.disruptionChoice;
            }
            return 'Route ' + (ds.routeChoice || '—');
        }

        _updateRound(state) {
            var round = state.currentPeriod || 1;
            if (round > 4) round = 4;
            for (var i = 1; i <= 4; i++) {
                var block = document.getElementById('round' + i + 'Block');
                if (block) {
                    if (i === round) block.classList.add('active');
                    else block.classList.remove('active');
                }
            }
            var titleEl = document.getElementById('briefingTitle');
            var bodyEl = document.getElementById('briefingBody');
            if (titleEl && window.mySimulation) {
                titleEl.textContent = window.mySimulation.t('r' + round + '_briefing_title');
            }
            if (bodyEl && window.mySimulation) {
                bodyEl.innerHTML = window.mySimulation.t('r' + round + '_briefing_body');
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('marginDisplay', 'domainState.margin', function(v) {
                if (v === null || v === undefined) return '—';
                var prefix = v >= 0 ? '$' : '-$';
                return prefix + Math.abs(Math.round(v)).toLocaleString();
            });
            uiManager.bind('probDisplay', 'domainState.probArrival', function(v) {
                if (!v) return '—';
                return Math.round(v * 100) + '%';
            });
            uiManager.bind('transitDisplay', 'domainState.transitDays', function(v) {
                return v ? v + ' d' : '—';
            });
            uiManager.bind('costDisplay', 'domainState.landedCost', function(v) {
                return v ? '$' + Math.round(v) + '/t' : '—';
            });
        }

        getChartConfig() {
            return {
                probChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'P(arrival ≤ deadline) %',
                            data: [],
                            borderColor: '#00b4d8',
                            backgroundColor: 'rgba(0,180,216,0.15)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.25,
                            pointBackgroundColor: '#00b4d8',
                            pointRadius: 5
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { labels: { color: '#b8c8da' } }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 100,
                                ticks: { color: '#8aa6c2', callback: function(v) { return v + '%'; } },
                                grid: { color: 'rgba(45,66,89,0.5)' }
                            },
                            x: {
                                ticks: { color: '#8aa6c2' },
                                grid: { color: 'rgba(45,66,89,0.3)' }
                            }
                        }
                    }
                },
                marginChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Net Margin (USD)',
                            data: [],
                            backgroundColor: 'rgba(6,214,160,0.55)',
                            borderColor: '#06d6a0',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { labels: { color: '#b8c8da' } }
                        },
                        scales: {
                            y: {
                                ticks: {
                                    color: '#8aa6c2',
                                    callback: function(v) { return '$' + (v / 1000).toFixed(0) + 'k'; }
                                },
                                grid: { color: 'rgba(45,66,89,0.5)' }
                            },
                            x: {
                                ticks: { color: '#8aa6c2' },
                                grid: { color: 'rgba(45,66,89,0.3)' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.probHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                probChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.probHistory }]
                },
                marginChart: {
                    labels: labels,
