        getHint(state, results) {
            var ds = state.domainState;
            var round = state.currentPeriod || 1;
            if (round === 1 && results && ds.routeChoice === 'A' && ds.bufferDays === 0) {
                return window.mySimulation.t('hint_no_buffer');
            }
            if (round === 2 && ds.disruptionChoice === 'A') {
                return window.mySimulation.t('hint_wait_risk');
            }
            if (round === 2 && ds.disruptionChoice === 'D') {
                return window.mySimulation.t('hint_air_margin');
            }
            if (round === 3 && ds.vuceChoice === 'sequential') {
                return window.mySimulation.t('hint_vuce_serial');
            }
            if (round === 3 && ds.aeoChoice === 'no') {
                return window.mySimulation.t('hint_aeo_skip');
            }
            if (round === 3 && ds.extensionChoice === 'rebate_only') {
                return window.mySimulation.t('hint_rebate_unpaired');
            }
            if (round === 4 && ds.kpiChoice === 'cost') {
                return window.mySimulation.t('hint_wrong_kpi_cost');
            }
            if (round === 4 && ds.kpiChoice === 'margin') {
                return window.mySimulation.t('hint_wrong_kpi_margin');
            }
            if (results && results.probArrival < 0.6) {
                return window.mySimulation.t('hint_low_prob');
            }
            if (results && results.margin < 0) {
                return window.mySimulation.t('hint_negative_margin');
            }
            return null;
        }

